from pathlib import Path
for name in ['src/vue/pages/FeishuPage.vue','src/vue/pages/FeishuTaskBoard.vue']:
 p=Path(name); s=p.read_text(encoding='utf-8')
 s=s.replace("import CalmySelect from '@/vue/components/CalmySelect.vue'\n", '')
 if name.endswith('FeishuPage.vue'):
  s=s.replace('<CalmySelect id="feishu-project-picker" ariaLabel="飞书任务关联项目" v-model="projectId" :options="projectOptions" :disabled="snapshot.saving||!!snapshot.tableErrors.projects||!projectField||![18,21].includes(projectField.type)"/>', '<select id="feishu-project-picker" aria-label="飞书任务关联项目" v-model="projectId" :disabled="snapshot.saving||!!snapshot.tableErrors.projects||!projectField||![18,21].includes(projectField.type)"><option v-for="option in projectOptions" :key="option.value" :value="option.value">{{option.label}}</option></select>')
  s=s.replace('<CalmySelect :id="`feishu-task-status-${record.record_id}`" :ariaLabel="`${recordTitle(record,\'tasks\')}状态`" :model-value="text(record,\'tasks\',\'status\')||\'未设置\'" :options="taskStatusOptions(record)" :disabled="!snapshot.ready||snapshot.saving||!taskStatusOptions(record).some(option => !option.disabled)" compact @change="changeStatus(record,$event)"/>', '<select :aria-label="`${recordTitle(record, \'tasks\')}状态`" :value="text(record, \'tasks\', \'status\')||\'未设置\'" :disabled="!snapshot.ready||snapshot.saving||!taskStatusOptions(record).some(option => !option.disabled)" @change="changeStatus(record, ($event.target as HTMLSelectElement).value)"><option v-for="option in taskStatusOptions(record)" :key="option.value" :value="option.value" :disabled="option.disabled">{{option.label}}</option></select>')
  s=s.replace('<CalmySelect :id="`feishu-related-task-status-${task.record_id}`" :ariaLabel="`${recordTitle(task,\'tasks\')}状态`" :model-value="text(task,\'tasks\',\'status\')||\'未设置\'" :options="taskStatusOptions(task)" :disabled="!snapshot.ready||snapshot.saving||!taskStatusOptions(task).some(option=>!option.disabled)" compact @change="changeRelatedTaskStatus(task,$event)"/>', '<select :aria-label="`${recordTitle(task, \'tasks\')}状态`" :value="text(task, \'tasks\', \'status\')||\'未设置\'" :disabled="!snapshot.ready||snapshot.saving||!taskStatusOptions(task).some(option=>!option.disabled)" @change="changeRelatedTaskStatus(task, ($event.target as HTMLSelectElement).value)"><option v-for="option in taskStatusOptions(task)" :key="option.value" :value="option.value" :disabled="option.disabled">{{option.label}}</option></select>')
 else:
  s=s.replace('<CalmySelect id="feishu-board-project" ariaLabel="飞书任务关联项目" v-model="projectId" :options="projectOptions" :disabled="snapshot.saving||!!snapshot.tableErrors.projects"/>', '<select id="feishu-board-project" aria-label="飞书任务关联项目" v-model="projectId" :disabled="snapshot.saving||!!snapshot.tableErrors.projects"><option v-for="option in projectOptions" :key="option.value" :value="option.value">{{option.label}}</option></select>')
  s=s.replace('<CalmySelect :id="`feishu-board-status-${record.record_id}`" :ariaLabel="`${title(record)}状态`" :model-value="status(record)" :options="taskStatusOptions(record)" :disabled="!snapshot.ready||snapshot.saving||!taskStatusOptions(record).some(option=>!option.disabled)" compact @change="move(record.record_id,$event)"/>', '<select :aria-label="`${title(record)}状态`" :value="status(record)" :disabled="!snapshot.ready||snapshot.saving||!taskStatusOptions(record).some(option=>!option.disabled)" @change="move(record.record_id, ($event.target as HTMLSelectElement).value)"><option v-for="option in taskStatusOptions(record)" :key="option.value" :value="option.value" :disabled="option.disabled">{{option.label}}</option></select>')
 p.write_text(s, encoding='utf-8')
p=Path('src/__tests__/vue-feishu-parity.test.ts')
s=p.read_text(encoding='utf-8').replace("    await page.get('[aria-label=\"写迁移计划状态\"]').trigger('click')\n    await page.get('[role=\"option\"][data-value=\"进行中\"]').trigger('click')", "    await page.get('[aria-label=\"写迁移计划状态\"]').setValue('进行中')")
p.write_text(s, encoding='utf-8')
